-- Nilgiribytes – Phase 1 demo data
-- Sizes and combo contents are embedded as JSON on Product/Combo.
-- Generated from src/data/catalog.json and src/data/blog.json.
-- Run table_creation.sql first; this script expects empty tables.
-- Re-run table_deletion.sql before applying this file again.

SET NAMES utf8mb4;

START TRANSACTION;

-- Categories
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `sortOrder` = VALUES(`sortOrder`), `updatedAt` = NOW(3);

-- Products
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `description` = VALUES(`description`), `sizes` = VALUES(`sizes`), `posterUrl` = VALUES(`posterUrl`), `imageUrl` = VALUES(`imageUrl`), `sortOrder` = VALUES(`sortOrder`), `updatedAt` = NOW(3);

-- Combos
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `description` = VALUES(`description`), `items` = VALUES(`items`), `imageUrl` = VALUES(`imageUrl`), `weightLabel` = VALUES(`weightLabel`), `pricePaise` = VALUES(`pricePaise`), `sortOrder` = VALUES(`sortOrder`), `updatedAt` = NOW(3);

-- Blog posts
ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `category` = VALUES(`category`), `author` = VALUES(`author`), `date` = VALUES(`date`), `coverImage` = VALUES(`coverImage`), `excerpt` = VALUES(`excerpt`), `status` = VALUES(`status`), `content` = VALUES(`content`), `readingTimeMin` = VALUES(`readingTimeMin`), `updatedAt` = NOW(3);

-- Admin user (username: Sujith, password: Sujith@123)
ON DUPLICATE KEY UPDATE `passwordHash` = VALUES(`passwordHash`);

COMMIT;
